import os
import time
from typing import Optional

import requests


class AssemblyAITranscriptionClient:
    def __init__(self, api_key: Optional[str] = None, poll_interval: float = 5.0, timeout: float = 1800.0):
        self.api_key = api_key or os.environ.get("ASSEMBLYAI_API_KEY")
        if not self.api_key:
            raise ValueError("Missing ASSEMBLYAI_API_KEY")
        self.poll_interval = poll_interval
        self.timeout = timeout
        self.base_url = "https://api.assemblyai.com/v2"
        self.headers = {"authorization": self.api_key}

    def get_transcript(self, audio_url: str) -> str:
        create_resp = requests.post(
            f"{self.base_url}/transcript",
            headers=self.headers,
            json={"audio_url": audio_url},
            timeout=30,
        )
        create_resp.raise_for_status()
        transcript_id = create_resp.json()["id"]

        deadline = time.time() + self.timeout
        while True:
            if time.time() > deadline:
                raise TimeoutError("Transcription polling timed out")

            status_resp = requests.get(
                f"{self.base_url}/transcript/{transcript_id}",
                headers=self.headers,
                timeout=30,
            )
            status_resp.raise_for_status()
            data = status_resp.json()
            status = data.get("status")

            if status == "completed":
                return data.get("text", "")
            if status == "error":
                raise RuntimeError(data.get("error", "Transcription failed"))

            time.sleep(self.poll_interval)
